import { z } from 'astro/zod';

import { repoPath } from './projects';

// Contract C1. Keyed by project slug (the markdown file name), generated by `npm run sync:projects` and committed.
// `updated` is the committer date of the newest commit on the repo's default branch; `created` is the repo's creation
// date (the project's stable date, which orders the index numbers). Both are ISO 8601 UTC timestamps. `description` is
// the repo's GitHub About text and `tech` its topics mapped to display names (src/lib/topicMap.ts), so the card copy
// follows GitHub. `capturedSha` is the default-branch commit the committed screenshot was taken at; it is absent until a
// project is first captured. Strict, so a stray key fails the build.
const projectMetaEntrySchema = z.strictObject({
    created: z.iso.datetime(),
    updated: z.iso.datetime(),
    description: z.string().trim().min(1),
    tech: z.array(z.string().min(1)).min(1),
    capturedSha: z
        .string()
        .regex(/^[0-9a-f]{40}$/, 'Expected a 40-character lowercase commit SHA')
        .optional(),
});
const projectMetaSchema = z.record(z.string(), projectMetaEntrySchema);
export type ProjectMetaEntry = z.output<typeof projectMetaEntrySchema>;
export type ProjectMeta = z.output<typeof projectMetaSchema>;

/** The card copy of a project, as the sync derived it from GitHub. */
export interface ProjectCopy {
    readonly description: string;
    readonly tech: readonly string[];
}

const commitsResponseSchema = z
    .array(
        z.object({
            sha: z.string().regex(/^[0-9a-f]{40}$/),
            commit: z.object({ committer: z.object({ date: z.iso.datetime() }) }),
        }),
    )
    .min(1, 'The repository has no commits');

// `description` is null on GitHub when the About text is empty; `topics` is always present on the repo endpoint.
const repoResponseSchema = z.object({
    created_at: z.iso.datetime(),
    description: z.string().nullable(),
    topics: z.array(z.string()),
});

/** The fields of a GitHub repo response the sync uses. */
export interface RepoFacts {
    readonly created: string;
    /** The About text, or `null` when it is empty. */
    readonly description: string | null;
    readonly topics: readonly string[];
}

/** The newest default-branch commit. */
export interface HeadCommit {
    readonly sha: string;
    readonly date: string;
}

/** Validates the parsed contents of `src/data/project-meta.json`. */
export function parseProjectMeta(data: unknown): ProjectMeta {
    return projectMetaSchema.parse(data);
}

/** The project's last-updated date, or `undefined` when the sync has not recorded one (the card then omits it). */
export function lastUpdatedFor(meta: ProjectMeta, slug: string): Date | undefined {
    const entry = meta[slug];
    return entry ? new Date(entry.updated) : undefined;
}

/** The project's creation date, or `undefined` when the sync has not recorded one (the index then numbers it last). */
export function createdFor(meta: ProjectMeta, slug: string): Date | undefined {
    const created = meta[slug]?.created;
    return created ? new Date(created) : undefined;
}

/**
 * The project's card copy. Throws when the sync has not recorded it, which fails the build: a card without a
 * description or tech chips must never reach production. Run `npm run sync:projects` after adding a project.
 */
export function copyFor(meta: ProjectMeta, slug: string): ProjectCopy {
    const entry = meta[slug];
    if (!entry) {
        throw new Error(
            `src/data/project-meta.json has no entry for "${slug}": run npm run sync:projects and commit the result`,
        );
    }
    return { description: entry.description, tech: entry.tech };
}

/** The URL of the repo itself: its `created_at`, About `description` and `topics`. */
export function repoApiUrl(repo: string): string {
    return `https://api.github.com/repos/${repoPath(repo)}`;
}

/** Extracts the creation date, About text and topics from a repo response. */
export function factsFromRepo(response: unknown): RepoFacts {
    const { created_at, description, topics } = repoResponseSchema.parse(response);
    return { created: created_at, description, topics };
}

/**
 * The first line of the sync bot's commit on main (contract C4: the squash-merged bot PR's title, which GitHub follows
 * with ` (#<number>)`). `headFromCommits` skips it.
 */
export const SYNC_COMMIT_TITLE = 'chore(projects): refresh project data';

/** The sync bot's fixed branch (contract C4); a merge commit of it is skipped like the squash commit. */
export const SYNC_BRANCH = 'bot/sync-projects';

/**
 * The URL of the repo's newest commits on its default branch (`per_page=30`, enough to look past the bot commits that
 * `headFromCommits` skips). The commits endpoint, unlike the repo's `pushed_at`, ignores pushes to other branches, and
 * the version bot and Dependabot push PR branches all the time.
 */
export function commitsApiUrl(repo: string): string {
    return `https://api.github.com/repos/${repoPath(repo)}/commits?per_page=30`;
}

/**
 * Extracts the SHA and committer date of the newest commit a person made from a `commits?per_page=30` response
 * (S2, reviewer finding F1). It skips a commit whose GitHub `author` is a bot account (`type: "Bot"`, which covers the
 * version bot, Dependabot and the sync App), a commit whose first message line starts with `SYNC_COMMIT_TITLE`, and a
 * merge commit whose first line is `Merge pull request #<n> from <owner>/bot/sync-projects`. Without this, the bot
 * PR merging into this repo would move this repo's own `updated` and open the next bot PR, forever. Throws when the
 * response is empty, malformed, or holds no commit that qualifies.
 */
export function headFromCommits(response: unknown): HeadCommit {
    const [newest] = commitsResponseSchema.parse(response);
    return { sha: newest.sha, date: newest.commit.committer.date };
}

/** Returns a copy of `meta` with `slug` set to `entry`. */
export function mergeProjectMeta(meta: ProjectMeta, slug: string, entry: ProjectMetaEntry): ProjectMeta {
    return { ...meta, [slug]: entry };
}

// Recursively sorts object keys so the serialized file does not depend on insertion order. Arrays keep their order:
// `tech` is shown in that order.
function sortKeys(value: unknown): unknown {
    if (Array.isArray(value)) return value.map(sortKeys);
    if (value !== null && typeof value === 'object') {
        return Object.fromEntries(
            Object.entries(value)
                .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
                .map(([key, inner]) => [key, sortKeys(inner)]),
        );
    }
    return value;
}

/**
 * The committed form of the meta file: keys sorted at every level (by code unit, so the order never depends on the
 * locale), two-space indent, trailing newline. Serializing a parsed file gives back the same bytes.
 */
export function serializeProjectMeta(meta: ProjectMeta): string {
    return `${JSON.stringify(sortKeys(meta), null, 2)}\n`;
}
